"OLAYLAR_GEZGINLER:1776-07-11:0":{"b": ["Cook aanza safari ya tatu kutafuta Njia ya Kaskazini-Magharibi", "f26ae1b9"], "d": ["Cook aliondoka Plymouth na Resolution; Discovery chini ya amri ya Clerke ilijiunga baadaye. Lengo lilikuwa kupata Njia ya Kaskazini-Magharibi inayokwenda kutoka Pasifiki hadi Atlantiki.", "691a9154"]},
"OLAYLAR_GEZGINLER:1777-11-02:0":{"b": ["Omai aachwa Huahine", "1aacec70"], "d": ["Omai, Mtahiti aliyepelekwa London, tarehe 2 Novemba 1777 alirudishwa nyumbani kwa kuwekwa Huahine; Cook kisha alimpa Clerke maagizo Ulietea.", "fd0125c5"]},
"OLAYLAR_GEZGINLER:1778-01-01:0":{"b": ["Cook aona Visiwa vya Hawaii kwa mara ya kwanza", "667d02ad"], "d": ["Cook alifika Kauai na Niihau Januari 1778; alivipa visiwa jina la 'Visiwa vya Sandwich'. Huu ndio mawasiliano ya kwanza ya Wazungu yaliyoandikwa na Hawaii.", "6fb79d44"]},
"OLAYLAR_GEZGINLER:1779-02-14:0":{"b": ["Cook auawa Kealakekua", "17a65c6a"], "d": ["Katika ziara yake ya pili Hawaii, katika mapigano yaliyozuka kwa wizi wa boti Cook aliuawa tarehe 14 Februari 1779 katika Ghuba ya Kealakekua (Karakakooa); mwili wake ulizikwa baharini tarehe 20 Februari.", "47ed2581"]},
"OLAYLAR_GEZGINLER:1779-04-28:0":{"b": ["Meli zafika Kamchatka", "8fc59004"], "d": ["Baada ya kifo cha Cook, meli chini ya amri ya Clerke zilitia nanga katika Ghuba ya Avacha huko Kamchatka, Pasifiki ya Kaskazini.", "4c0e2830"]},
